import { HttpClient } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { MouseData } from '../models/MouseData';

@Injectable({
  providedIn: 'root'
})
export class MouseDataTransferService {

  private apiUrl = 'http://localhost:4000/test';

  constructor(private http: HttpClient) {}

  sendMouseData(testName: string, events: MouseData[], sessionId: string ){
      let data={
      test:testName, mousedata:events
    }
    return this.http.post<string>(`${this.apiUrl}/sendData`, data)

  }
}
